package org.eclipse.rdf4j.query.algebra.evaluation.function.string.ext;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.query.algebra.evaluation.ValueExprEvaluationException;
import org.eclipse.rdf4j.query.algebra.evaluation.function.support.FunctionArgs;

/**
 * Shared implementation of {@code strf:lpad} and {@code strf:rpad}: {@code pad(s, n [, fill])} pads {@code s} with
 * {@code fill} (default a single space) up to {@code n} code points, or truncates it to {@code n} code points when it
 * is longer (PostgreSQL semantics).
 */
abstract class AbstractPadFunction extends StringFunction {

	/** Longest result (in code points), as for strf:repeat; larger targets are an evaluation error. */
	static final int MAX_RESULT_LENGTH = 1 << 26;

	@Override
	public Literal evaluate(ValueFactory valueFactory, Value... args) throws ValueExprEvaluationException {
		FunctionArgs.arity(this, args, 2, 3);
		Literal source = FunctionArgs.stringLiteral(this, args[0]);
		int target = FunctionArgs.toInt(this, args[1]);
		String fill = args.length == 3 ? FunctionArgs.string(this, args[2]) : " ";
		String s = source.getLabel();
		int length = FunctionArgs.codePointLength(s);
		if (target <= 0) {
			return FunctionArgs.sameKind("", source, valueFactory);
		}
		if (target > MAX_RESULT_LENGTH) {
			throw new ValueExprEvaluationException("Result of " + getURI() + " is too large: " + target
					+ " code points");
		}
		if (length == target) {
			return source;
		}
		if (length > target) {
			return FunctionArgs.sameKind(truncate(s, target), source, valueFactory);
		}
		if (fill.isEmpty()) {
			return source;
		}
		int missing = target - length;
		StringBuilder padding = new StringBuilder(missing * 2);
		int fillLength = FunctionArgs.codePointLength(fill);
		while (missing >= fillLength) {
			padding.append(fill);
			missing -= fillLength;
		}
		if (missing > 0) {
			padding.append(FunctionArgs.substringByCodePoints(fill, 0, missing));
		}
		return FunctionArgs.sameKind(combine(s, padding), source, valueFactory);
	}

	protected abstract String truncate(String s, int target);

	protected abstract String combine(String s, StringBuilder padding);
}
